<article class="content-card"><div class="flex justify-between gap-2 items-center"><x-platform :platform="$post->platform"/><x-status :status="$post->status"/></div><div class="content-card-body"><p class="eyebrow">{{ $post->content_type }} @if($post->campaign->is_demo)<span class="sample-label">SAMPLE</span>@endif</p><h3><a href="{{ route('posts.show',$post) }}">{{ $post->post_idea }}</a></h3><p class="muted line-clamp-3 mt-3 text-sm">{{ $post->caption }}</p></div><div class="content-card-footer"><span>{{ ($post->scheduled_date ?? $post->planned_date)->format('d M Y') }}</span><a href="{{ route('posts.show',$post) }}" class="text-link">{{ $post->status === 'Draft' ? 'Review content' : 'View post' }}<x-icon name="arrow"/></a></div></article>
